/**
 * Cursor-account mode for GitLab channels.
 *
 * `gitlabChannel({ cursorAccount })` declares that outbound GitLab calls run
 * through the Cursor SCM proxy (`/v0/gitlab-proxy`) with the tenant's
 * credential swapped in server-side. The serve host binds the Cursor API key
 * and the proxy transport at startup when `--cursor-scm-proxy` is set; until
 * then `ctx.gitlab` falls back to direct `GITLAB_TOKEN` access.
 */
import { resolveCursorScmProxyUrl } from "../github/cursor-account.js";
export const CURSOR_GITLAB_MAX_PROJECTS = 20;
/** `group/project`, with nested groups (`group/sub/project`). */
const CURSOR_GITLAB_PROJECT_PATTERN = /^[A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)+$/;
const runtimeByDefinition = new WeakMap();
export function parseCursorGitLabProjectScope(values) {
    const projects = [
        ...new Set(values
            .map((project) => project
            .trim()
            .replace(/^\/+|\/+$/g, "")
            .toLowerCase())
            .filter(Boolean)),
    ];
    if (projects.length === 0) {
        throw new Error("gitlabChannel({ cursorAccount }) requires at least one project.");
    }
    if (projects.length > CURSOR_GITLAB_MAX_PROJECTS) {
        throw new Error(`gitlabChannel({ cursorAccount }) supports at most ${CURSOR_GITLAB_MAX_PROJECTS} projects.`);
    }
    for (const project of projects) {
        if (!CURSOR_GITLAB_PROJECT_PATTERN.test(project) || project.includes("..")) {
            throw new Error(`Invalid GitLab project "${project}"; expected group/project.`);
        }
    }
    return { projects };
}
export function createPendingCursorGitLabCredentials() {
    let getApiKey;
    let transport;
    return {
        bind(next) {
            getApiKey = next;
        },
        bindProxyTransport(next) {
            transport = next;
        },
        getProxyTransport() {
            if (getApiKey === undefined || transport === undefined) {
                return undefined;
            }
            return { ...transport, getApiKey };
        },
    };
}
/** GitLab-proxy base URL (`/v0/gitlab-proxy`, `AGENT_SERVE_GITLAB_PROXY_URL`). */
export function resolveCursorGitLabProxyUrl(backendBaseUrl) {
    return resolveCursorScmProxyUrl("gitlab", backendBaseUrl);
}
export function registerGitLabCursorAccountRuntime(definition, runtime) {
    runtimeByDefinition.set(definition, runtime);
}
export function getGitLabCursorAccountRuntime(definition) {
    return runtimeByDefinition.get(definition);
}
